L3_1.m_CharStrID = "FISHER_NPC_NULL_NULL"
L3_1.m_Talk_KOREA = "바다 한복판이 번쩍 하더니, 거기서 사람이 떨어질 거라곤 꿈에도 몰랐거든요."
L3_1.m_fTalkTime = 0.03
L3_1.m_Talk_JPN = "海のど真ん中がピカーっと光ったと思ったら、人が落ちてきたっしょ？　そんなこと夢にも思わねぇっすから。"
