L5_1.m_Pos = "L"
L5_1.m_Talk_KOREA = "마침 배가 근처에 있어서 살았어요. 저희 중 한 명이 수영을 전혀 못 하거든요."
L5_1.m_fTalkTime = 0.03
L5_1.m_Talk_JPN = "ちょうど近くに船があって助かったよ。一人、全然泳げない人がいたから。"
L5_1.m_Talk_ENG = "Lucky for us your boat was nearby. One of us can't swim at all."
L5_1.m_Talk_TWN = "我們之中有人完全不會游泳，幸好船就在附近才得救。"
L5_1.m_Talk_DEU = "Lucky for us your boat was nearby. One of us can't swim at all."
L5_1.m_Talk_FRA = "Lucky for us your boat was nearby. One of us can't swim at all."
L6_1 = {}
