L6_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_IDLE"
L6_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L6_1.m_Pos = "R"
L6_1.m_Talk_KOREA = "말했다시피 우린 훈련 중인 카운터다. 이 녀석의 공간이동 능력을 함께 시험하다 이렇게 됐지."
L6_1.m_fTalkTime = 0.03
L6_1.m_Talk_JPN = "さっきも話したように、私たちは訓練中のカウンターだ。こいつの空間移動能力をテストしていたらこうなった。"
L6_1.m_Talk_ENG = "Like I said, we're Counters in training. We were testing this one's teleportation ability together when it happened."
L6_1.m_Talk_TWN = "就像之前說的，我們是在訓練中的制裁者。在測試這傢伙的空間移動能力時才變成這樣。"
