L10_1.m_Face = "UNIT_SURPRISE"
L10_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L10_1.m_Pos = "C"
L10_1.m_Crash = 30
L10_1.m_Talk_KOREA = "으악! 네, 넵! 전 공간이동 능력을 쓰는 카운터 훈련생입니닷! 제 실력이 미흡해서 시민 분께 신세를 졌습니다!"
L10_1.m_fTalkTime = 0.03
L10_1.m_Talk_JPN = "わあっ！　は、はい！　私は空間移動能力を使うカウンター訓練生です！　私の実力が足りなくて、市民の方にご迷惑をおかけしました！"
L10_1.m_Talk_ENG = "Aah! O-okay! I'm a Counter trainee with teleportation abilities! My skills weren't up to par, so we ended up troubling a civilian!"
L10_1.m_Talk_TWN = "啊！是、是的！我是使用空間移動能力的制裁者訓練生！因為我實力不足，才會麻煩您！"
L10_1.m_Talk_DEU = "Aah! O-okay! I'm a Counter trainee with teleportation abilities! My skills weren't up to par, so we ended up troubling a civilian!"
L10_1.m_Talk_FRA = "Aah! O-okay! I'm a Counter trainee with teleportation abilities! My skills weren't up to par, so we ended up troubling a civilian!"
