L12_1.m_CharStrID = "FISHER_NPC_NULL_NULL"
L12_1.m_Talk_KOREA = "공간이동이라니 신기하네요. 능력을 쓸 때는 특별한 포즈 같은 거라도 취하나요?"
L12_1.m_fTalkTime = 0.03
L12_1.m_Talk_JPN = "空間移動なんて不思議っすね。能力を使う時には、特別なポーズを取ったりするんすか？"
L12_1.m_Talk_ENG = "Teleportation, huh? That's amazing. Do you strike some kind of special pose when you use it?"
