L21_1.m_CharStrID = "FISHER_NPC_NULL_NULL"
L21_1.m_Talk_KOREA = "생각보다 어린 친구들이라 놀랐어요. 뉴스로 소식은 들었는데, 초능력자들이 우리 사회에 그렇게 많았다는 사실이 아직은 좀 낯설기도 하고요."
L21_1.m_fTalkTime = 0.03
L21_1.m_Talk_JPN = "それにしても、思ったより若くてビックリしたっすよ。ニュースで聞いてはいたけど、超能力者がこの社会にそんなに多かったなんて、まだ実感が湧かねぇっす。"
L21_1.m_Talk_ENG = "I'm surprised you're younger than I expected. I heard about it on the news, but it's still a little strange getting used to the fact that there are so many people with superpowers in our society."
L21_1.m_Talk_TWN = "沒想到你們這麼年輕。雖然新聞有報導，但還是不太習慣社會上有這麼多超能力者。"
L21_1.m_Talk_DEU = "I'm surprised you're younger than I expected. I heard about it on the news, but it's still a little strange getting used to the fact that there are so many people with superpowers in our society."
L21_1.m_Talk_FRA = "I'm surprised you're younger than I expected. I heard about it on the news, but it's still a little strange getting used to the fact that there are so many people with superpowers in our society."
