L22_1.m_fWaitTime = 0
L22_1.m_CharStrID = "FISHER_NPC_NULL_NULL"
L22_1.m_Talk_KOREA = "여러분도 다른 카운터 분들처럼 관리국에 들어가기 위해 훈련하고 계신 거죠?"
L22_1.m_fTalkTime = 0.03
L22_1.m_Talk_JPN = "皆さんも他のカウンターみたく管理局に入るために訓練してるんすよね？"
L22_1.m_Talk_ENG = "You're training to join the Administration like the other Counters, right?"
L22_1.m_Talk_TWN = "你們也像其他制裁者一樣，為了進入管理局在訓練吧？"
L22_1.m_Talk_DEU = "You're training to join the Administration like the other Counters, right?"
L22_1.m_Talk_FRA = "You're training to join the Administration like the other Counters, right?"
L23_1 = {}
L23_1.m_CutScenKey_Talk = "EP15_ACT2_INTERLUDE8@15#Talk"
L23_1.m_CutScenProcessKey = 23
L23_1.m_CutScenID = 696
L23_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L23_1.m_bWaitClick = true
L23_1.m_fWaitTime = 0
L23_1.m_Face = "UNIT_IDLE"
L23_1.m_CharStrID = "HILDE_FENRIR_NULL_NULL"
L23_1.m_Pos = "C"
L23_1.m_Talk_KOREA = "그래. 마침 오늘 그라운드 원에 공인 선발 시험이 있어서 하루 묵을 알아보던 중이었다."
L23_1.m_fTalkTime = 0.03
L23_1.m_Talk_JPN = "ああ。ちょうど今日グラウンド・ワンで公認選抜試験があって、一晩泊れるところを探していたんだ。"
L23_1.m_Talk_ENG = "That's right. There was an official audition at Ground One today, so we were looking for somewhere to stay the night."
L23_1.m_Talk_TWN = "對。剛好今天在G1有正式選拔考試，我們正打算找地方住一晚。"
L23_1.m_Talk_DEU = "That's right. There was an official audition at Ground One today, so we were looking for somewhere to stay the night."
L23_1.m_Talk_FRA = "That's right. There was an official audition at Ground One today, so we were looking for somewhere to stay the night."
