L25_1.m_fWaitTime = 0
L25_1.m_CharStrID = "FISHER_NPC_NULL_NULL"
L25_1.m_Talk_KOREA = "그라운드 원... 그렇죠. 벌써 다들 그런 이름으로 부르는군요."
L25_1.m_fTalkTime = 0.03
L25_1.m_Talk_JPN = "グラウンド・ワン……そうっすか。もうみんなその名前で呼んでるんすね。"
L25_1.m_Talk_ENG = "Ground One... right. Everyone's already calling it that."
L25_1.m_Talk_TWN = "G1啊……也對，現在大家都這麼叫了呢。"
L25_1.m_Talk_DEU = "Ground One... right. Everyone's already calling it that."
L25_1.m_Talk_FRA = "Ground One... right. Everyone's already calling it that."
L26_1 = {}
L26_1.m_CutScenKey_Talk = "EP15_ACT2_INTERLUDE8@17#Talk"
L26_1.m_CutScenProcessKey = 26
L26_1.m_CutScenID = 696
L26_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_CharStrID = "FISHER_NPC_NULL_NULL"
L26_1.m_Talk_KOREA = "하긴, 저 대균열이라는 것이 도시를 집어삼킨 뒤로는 완전히 다른 곳이 됐으니까요."
L26_1.m_fTalkTime = 0.03
L26_1.m_Talk_JPN = "まあ、あの大亀裂っちゅうのが都市を飲み込んでからは、完全に別の場所になっちまったっすから。"
L26_1.m_Talk_ENG = "Well, once that Grand Dimension Crevice swallowed up the city, it really did become a completely different place."
L26_1.m_Talk_TWN = "畢竟自從大峽谷吞噬城市之後，這裡已經完全變成另一個地方了。"
L26_1.m_Talk_DEU = "Well, once that Grand Dimension Crevice swallowed up the city, it really did become a completely different place."
L26_1.m_Talk_FRA = "Well, once that Grand Dimension Crevice swallowed up the city, it really did become a completely different place."
