L32_1 = {}
L32_1.m_CutScenKey_Talk = "EP15_ACT2_INTERLUDE8@21#Talk"
L32_1.m_CutScenProcessKey = 32
L32_1.m_CutScenID = 696
L32_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L32_1.m_bWaitClick = true
L32_1.m_fWaitTime = 0
L32_1.m_CharStrID = "FISHER_NPC_NULL_NULL"
L32_1.m_Talk_KOREA = "그땐 세상이 다 끝나는 줄 알았는데, 관리국 덕에 다시 사람이 살 수 있는 곳이 되어가고 있다는 게 느껴지거든요."
L32_1.m_fTalkTime = 0.03
L32_1.m_Talk_JPN = "当時は世界が終わると思ったっすけど、管理局のおかげでまただんだん人が住める場所になっている気がするっすよ。"
L32_1.m_Talk_ENG = "Back then, I thought the world was over, but thanks to the Administration, it feels like it's becoming a place people can live in again."
L32_1.m_Talk_TWN = "當時我以為世界真的要滅亡了。但現在我能感覺到在管理局的努力下，這裡正重新變成能讓人生活的地方。"
L32_1.m_Talk_DEU = "Back then, I thought the world was over, but thanks to the Administration, it feels like it's becoming a place people can live in again."
L32_1.m_Talk_FRA = "Back then, I thought the world was over, but thanks to the Administration, it feels like it's becoming a place people can live in again."
L33_1 = {}
L33_1.m_CutScenKey_Talk = "EP15_ACT2_INTERLUDE8@22#Talk"
L33_1.m_CutScenProcessKey = 33
L33_1.m_CutScenID = 696
L33_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L33_1.m_bWaitClick = true
L33_1.m_fWaitTime = 0
L33_1.m_CharStrID = "FISHER_NPC_NULL_NULL"
L33_1.m_Talk_KOREA = "아마... 이런 식으로 20년 정도만 지나면, 아무 걱정 없던 다시 원래의 삶으로 돌아가 있겠죠?"
L33_1.m_fTalkTime = 0.03
L33_1.m_Talk_JPN = "たぶん……こんな感じで20年くらい経てば、何の心配もなかった元の生活に戻れるんじゃないっすかね。"
L33_1.m_Talk_ENG = "Maybe... if another twenty years pass like this, we'll be back to our old lives without a single worry, don't you think?"
L33_1.m_Talk_TWN = "大概……再過20年左右，大家就能回到以前那種毫無煩惱的生活吧？"
L33_1.m_Talk_DEU = "Maybe... if another twenty years pass like this, we'll be back to our old lives without a single worry, don't you think?"
L33_1.m_Talk_FRA = "Maybe... if another twenty years pass like this, we'll be back to our old lives without a single worry, don't you think?"
