L44_1 = {}
L44_1.m_CutScenKey_Talk = "EP15_ACT2_INTERLUDE8@27#Talk"
L44_1.m_CutScenProcessKey = 44
L44_1.m_CutScenID = 696
L44_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L44_1.m_bWaitClick = true
L44_1.m_fWaitTime = 0
L44_1.m_CharStrID = "FISHER_NPC_NULL_NULL"
L44_1.m_Talk_KOREA = "여기서 좀 더 가시면 관리국에서 마련한 캠프가 있습니다."
L44_1.m_fTalkTime = 0.03
L44_1.m_Talk_JPN = "ここからもう少し行ったところに、管理局が建てたキャンプがあるっす。"
L44_1.m_Talk_ENG = "If you go a little farther from here, there's a camp the Administration set up."
L44_1.m_Talk_TWN = "再往前走一點，就有管理局設立的營地。"
L44_1.m_Talk_DEU = "If you go a little farther from here, there's a camp the Administration set up."
L44_1.m_Talk_FRA = "If you go a little farther from here, there's a camp the Administration set up."
L45_1 = {}
L45_1.m_CutScenKey_Talk = "EP15_ACT2_INTERLUDE8@28#Talk"
L45_1.m_CutScenProcessKey = 45
L45_1.m_CutScenID = 696
L45_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L45_1.m_bWaitClick = true
L45_1.m_fWaitTime = 0
L45_1.m_CharStrID = "FISHER_NPC_NULL_NULL"
L45_1.m_Talk_KOREA = "호텔은 아니지만, 하루 묵어가기엔 부담 없을 거에요. 관리국 직원 분들도 많이 계시거든요."
L45_1.m_fTalkTime = 0.03
L45_1.m_Talk_JPN = "ホテルじゃないが、一晩泊るには問題ないはずっす。管理局職員もたくさんいるし。"
L45_1.m_Talk_ENG = "It's not a hotel, but it's a fine place to stay for a night. There are plenty of Administration staff there too."
L45_1.m_Talk_TWN = "雖然不是飯店，但住一晚沒問題。那裡也有很多管理局的人。"
L45_1.m_Talk_DEU = "It's not a hotel, but it's a fine place to stay for a night. There are plenty of Administration staff there too."
L45_1.m_Talk_FRA = "It's not a hotel, but it's a fine place to stay for a night. There are plenty of Administration staff there too."
L46_1 = {}
L46_1.m_CutScenKey_Talk = "EP15_ACT2_INTERLUDE8@29#Talk"
L46_1.m_CutScenProcessKey = 46
