L46_1.m_CharStrID = "YOOMINA_FENRIR_NULL_NULL"
L46_1.m_Pos = "L"
L46_1.m_Talk_KOREA = "여기까지 안내해줘서 고마워, 아저씨."
L46_1.m_fTalkTime = 0.03
L46_1.m_Talk_JPN = "ここまで案内してくれてありがとう、おじさん。"
L46_1.m_Talk_ENG = "Thanks for showing us the way, mister."
L46_1.m_Talk_TWN = "謝謝你帶我們到這裡，大叔。"
L46_1.m_Talk_DEU = "Thanks for showing us the way, mister."
L46_1.m_Talk_FRA = "Thanks for showing us the way, mister."
L47_1 = {}
L47_1.m_CutScenKey_Talk = "EP15_ACT2_INTERLUDE8@30#Talk"
L47_1.m_CutScenProcessKey = 47
L47_1.m_CutScenID = 696
L47_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L47_1.m_bWaitClick = true
L47_1.m_fWaitTime = 0
L47_1.m_Face = "UNIT_PRIDE"
L47_1.m_CharStrID = "INTERN_FENRIR_NULL_NULL"
L47_1.m_Pos = "R"
L47_1.m_Talk_KOREA = "공간이동 능력자 노엘! 도와주신 선생님께 감사를 표합니다!"
L47_1.m_fTalkTime = 0.03
L48_1 = "空間移動能力者のノエル！　助けていただき感謝いたします！"
L47_1.m_Talk_JPN = L48_1
L48_1 = "Noelle the teleporter expresses her gratitude to the gentleman who helped us!"
L47_1.m_Talk_ENG = L48_1
