L3_1 = "그래. 알려고 하면 다칠 거다. 세계침식률에 큰 영향을 초래하겠지."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "ああ。詮索しない方がいい。世界侵食率に大きな影響を及ぼすことになるだろう。"
