L46_1.m_CharStrID = L47_1
L46_1.m_Pos = "R"
L47_1 = "설마, 나는 기계몸이니 짐칸에 실어도 괜찮다- 같은 고리타분한 말씀을 하려는 건 아니죠?"
L46_1.m_Talk_KOREA = L47_1
L46_1.m_fTalkTime = 0.03
L47_1 = "まさか、「某は機械の体をしているから荷物置き場に置いてもいい」みたいなお堅いこと言おうとしているのではないでしょうね？"
L46_1.m_Talk_JPN = L47_1
L47_1 = "You're not about to say something cliche like, \"I have a machine body, so you can just toss me in the cargo hold,\" are you?"
L46_1.m_Talk_ENG = L47_1
L47_1 = "你該不會想說「反正我是機械身體，放在貨艙也沒關係」這種老掉牙的話吧？"
L46_1.m_Talk_TWN = L47_1
L47_1 = "You're not about to say something cliche like, \"I have a machine body, so you can just toss me in the cargo hold,\" are you?"
L46_1.m_Talk_DEU = L47_1
L47_1 = "You're not about to say something cliche like, \"I have a machine body, so you can just toss me in the cargo hold,\" are you?"
