L3_1 = "EP15_ACT2_INTERLUDE8@155#Talk"
L2_1.m_CutScenKey_Talk = L3_1
L3_1 = 202
L2_1.m_CutScenProcessKey = L3_1
L2_1.m_CutScenID = 696
L2_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L2_1.m_bWaitClick = true
L2_1.m_fWaitTime = 0
L2_1.m_Face = "UNIT_IDLE"
L3_1 = "SEOSAENG_ATELIER_ANAP_GAP"
L2_1.m_CharStrID = L3_1
L2_1.m_Pos = "C"
L3_1 = "과거로 돌아가, 과거를 바로잡고자 했소."
L2_1.m_Talk_KOREA = L3_1
L2_1.m_fTalkTime = 0.03
L3_1 = "過去に戻り、過去を正そうとしたのだ。"
L2_1.m_Talk_JPN = L3_1
L3_1 = "I wished to return to the past and set it right."
L2_1.m_Talk_ENG = L3_1
L3_1 = "為了回到過去、修正過去。"
L2_1.m_Talk_TWN = L3_1
L3_1 = "I wished to return to the past and set it right."
L2_1.m_Talk_DEU = L3_1
L3_1 = "I wished to return to the past and set it right."
L2_1.m_Talk_FRA = L3_1
L3_1 = {}
L4_1 = "EP15_ACT2_INTERLUDE8@156#Talk"
L3_1.m_CutScenKey_Talk = L4_1
L4_1 = 203
L3_1.m_CutScenProcessKey = L4_1
L3_1.m_CutScenID = 696
L3_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L3_1.m_bWaitClick = true
L3_1.m_fWaitTime = 0
L3_1.m_Face = "UNIT_IDLE"
L4_1 = "SEOSAENG_ATELIER_ANAP_GAP"
L3_1.m_CharStrID = L4_1
L3_1.m_Pos = "C"
L4_1 = "허나 틀린 생각이었지. 바로 잡아야 했던 것은 과거가 아닌 본인의 어수선한 마음이었으니."
L3_1.m_Talk_KOREA = L4_1
L3_1.m_fTalkTime = 0.03
L4_1 = "だが、それは間違っていた。正すべきは過去ではなく、某の乱れた心だったゆえ。"
L3_1.m_Talk_JPN = L4_1
L4_1 = "But that was the wrong idea. What needed setting right was not the past, but my own troubled heart."
L3_1.m_Talk_ENG = L4_1
L4_1 = "但那是錯誤的想法。真正需要修正的不是過去，而是我自己混亂不安的心。"
L3_1.m_Talk_TWN = L4_1
L4_1 = "But that was the wrong idea. What needed setting right was not the past, but my own troubled heart."
L3_1.m_Talk_DEU = L4_1
L4_1 = "But that was the wrong idea. What needed setting right was not the past, but my own troubled heart."
L3_1.m_Talk_FRA = L4_1
L4_1 = {}
L5_1 = "EP15_ACT2_INTERLUDE8@157#Talk"
L4_1.m_CutScenKey_Talk = L5_1
L5_1 = 204
L4_1.m_CutScenProcessKey = L5_1
L4_1.m_CutScenID = 696
L4_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L4_1.m_bWaitClick = true
L4_1.m_fWaitTime = 0
L4_1.m_Face = "UNIT_DESPAIR"
L5_1 = "YEONHWA_ADMIN_NULL_NULL"
L4_1.m_CharStrID = L5_1
L4_1.m_Pos = "R"
L5_1 = "비관적으로 말씀하시는 걸 보니, 잘 풀리지 않았나 봐요."
L4_1.m_Talk_KOREA = L5_1
L4_1.m_fTalkTime = 0.03
L5_1 = "悲観的におっしゃるところを見ると、うまくいかなかったのですね。"
L4_1.m_Talk_JPN = L5_1
L5_1 = "The way you say that sounds pretty pessimistic. I take it things didn't work out very well?"
L4_1.m_Talk_ENG = L5_1
L5_1 = "你說得很悲觀，看來事情沒有成功。"
L4_1.m_Talk_TWN = L5_1
L5_1 = "The way you say that sounds pretty pessimistic. I take it things didn't work out very well?"
L4_1.m_Talk_DEU = L5_1
L5_1 = "The way you say that sounds pretty pessimistic. I take it things didn't work out very well?"
L4_1.m_Talk_FRA = L5_1
L5_1 = {}
L6_1 = "EP15_ACT2_INTERLUDE8@158#Talk"
L5_1.m_CutScenKey_Talk = L6_1
L6_1 = 205
L5_1.m_CutScenProcessKey = L6_1
L5_1.m_CutScenID = 696
L5_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L5_1.m_bWaitClick = true
L5_1.m_fWaitTime = 0
L5_1.m_Face = "UNIT_IDLE"
L6_1 = "SEOSAENG_ATELIER_ANAP_GAP"
L5_1.m_CharStrID = L6_1
L5_1.m_Pos = "C"
L6_1 = "아니. 그럼에도 결과적으로는... 모든 것이 잘 되었소."
L5_1.m_Talk_KOREA = L6_1
L5_1.m_fTalkTime = 0.03
L6_1 = "いや。それでも結果的には……すべてがうまくいった。"
L5_1.m_Talk_JPN = L6_1
L6_1 = "No. Even so, in the end... everything turned out okay."
L5_1.m_Talk_ENG = L6_1
L6_1 = "不。即便如此，從結果來看……一切都算順利。"
L5_1.m_Talk_TWN = L6_1
L6_1 = "No. Even so, in the end... everything turned out okay."
L5_1.m_Talk_DEU = L6_1
L6_1 = "No. Even so, in the end... everything turned out okay."
L5_1.m_Talk_FRA = L6_1
