L7_1 = "EP15_ACT2_INTERLUDE8@159#Talk"
L6_1.m_CutScenKey_Talk = L7_1
L7_1 = 206
L6_1.m_CutScenProcessKey = L7_1
L6_1.m_CutScenID = 696
L6_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L6_1.m_bWaitClick = true
L6_1.m_fWaitTime = 0
L6_1.m_Face = "UNIT_IDLE"
L7_1 = "SEOSAENG_ATELIER_ANAP_GAP"
L6_1.m_CharStrID = L7_1
L6_1.m_Pos = "C"
L7_1 = "육신은 건사하지 못했으나, 많은 이들의 부단한 노력 덕에 오늘을 살아갈 기회도 얻었지."
L6_1.m_Talk_KOREA = L7_1
L6_1.m_fTalkTime = 0.03
L7_1 = "肉体は守れなかったが、多くの者の弛まぬ努力により今日を生きる機会を与えられたのだ。"
L6_1.m_Talk_JPN = L7_1
L7_1 = "I failed to preserve my body, but thanks to the tireless efforts of many people, I was given the chance to live on into today."
L6_1.m_Talk_ENG = L7_1
L7_1 = "雖然失去肉身，但多虧許多人不斷的努力，我也得以活到今天。"
L6_1.m_Talk_TWN = L7_1
L7_1 = "I failed to preserve my body, but thanks to the tireless efforts of many people, I was given the chance to live on into today."
L6_1.m_Talk_DEU = L7_1
L7_1 = "I failed to preserve my body, but thanks to the tireless efforts of many people, I was given the chance to live on into today."
L6_1.m_Talk_FRA = L7_1
L7_1 = {}
L8_1 = "EP15_ACT2_INTERLUDE8@160#Talk"
L7_1.m_CutScenKey_Talk = L8_1
L8_1 = 207
L7_1.m_CutScenProcessKey = L8_1
L7_1.m_CutScenID = 696
L7_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L7_1.m_bWaitClick = true
L7_1.m_fWaitTime = 0
L7_1.m_Face = "UNIT_DESPAIR"
L8_1 = "YEONHWA_ADMIN_NULL_NULL"
L7_1.m_CharStrID = L8_1
L7_1.m_Pos = "R"
L8_1 = "이런 기계 몸에 갇힌 신세가 되었는데도, 정말 잘 된 게 맞나요?"
L7_1.m_Talk_KOREA = L8_1
L7_1.m_fTalkTime = 0.03
L8_1 = "こんな機械の体になっても、本当によかったと言えるのですか？"
L7_1.m_Talk_JPN = L8_1
L8_1 = "Even though you ended up trapped in a machine body like this, did things really turn out okay?"
L7_1.m_Talk_ENG = L8_1
L8_1 = "就算被困在機械身體裡，也算順利嗎？"
L7_1.m_Talk_TWN = L8_1
L8_1 = "Even though you ended up trapped in a machine body like this, did things really turn out okay?"
L7_1.m_Talk_DEU = L8_1
L8_1 = "Even though you ended up trapped in a machine body like this, did things really turn out okay?"
L7_1.m_Talk_FRA = L8_1
