L26_1 = "EP15_ACT2_INTERLUDE8@178#Talk"
L25_1.m_CutScenKey_Talk = L26_1
L26_1 = 225
L25_1.m_CutScenProcessKey = L26_1
L25_1.m_CutScenID = 696
L25_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L25_1.m_bWaitClick = true
L25_1.m_fWaitTime = 0
L25_1.m_Face = "UNIT_LAUGH"
L26_1 = "YEONHWA_ADMIN_NULL_NULL"
L25_1.m_CharStrID = L26_1
L25_1.m_Pos = "R"
L26_1 = "그 기계 뒤에 숨어있어도, 말투가 변해도, 저는 다 알 수 있어요. 당신은 당신이니까."
L25_1.m_Talk_KOREA = L26_1
L25_1.m_fTalkTime = 0.03
L26_1 = "その機械の裏に隠れていても、口調が変わっても、私には分かります。あなたはあなたですもの。"
L25_1.m_Talk_JPN = L26_1
L26_1 = "Even if you hide behind that machine, even if the way you speak has changed, I can still tell. You're still you."
L25_1.m_Talk_ENG = L26_1
L26_1 = "就算躲在那個機械身體後面、說話方式變了，我也知道是你。因為你就是你。"
L25_1.m_Talk_TWN = L26_1
L26_1 = "Even if you hide behind that machine, even if the way you speak has changed, I can still tell. You're still you."
L25_1.m_Talk_DEU = L26_1
L26_1 = "Even if you hide behind that machine, even if the way you speak has changed, I can still tell. You're still you."
L25_1.m_Talk_FRA = L26_1
L26_1 = {}
L27_1 = "EP15_ACT2_INTERLUDE8@179#Talk"
L26_1.m_CutScenKey_Talk = L27_1
L27_1 = 226
L26_1.m_CutScenProcessKey = L27_1
L26_1.m_CutScenID = 696
L26_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L26_1.m_bWaitClick = true
L26_1.m_fWaitTime = 0
L26_1.m_Face = "UNIT_DESPAIR"
L27_1 = "YEONHWA_ADMIN_NULL_NULL"
L26_1.m_CharStrID = L27_1
L26_1.m_Pos = "R"
L27_1 = "그런데 절 보고 반기기는커녕 정체를 숨는 걸 보면, 미래의 당신은 절 별로 좋아하지 않는 모양이네요."
L26_1.m_Talk_KOREA = L27_1
L26_1.m_fTalkTime = 0.03
L27_1 = "でも、私を見て嬉しく思うどころか正体を隠すところを見ると、未来のあなたは私のことがあまり好きではないようですね。"
L26_1.m_Talk_JPN = L27_1
L27_1 = "But instead of being happy to see me, you're hiding who you are, so I guess the future you doesn't like me very much."
L26_1.m_Talk_ENG = L27_1
L27_1 = "但看你見到我不但不開心，反而還隱藏身分，看來未來的你似乎不太喜歡我呢。"
L26_1.m_Talk_TWN = L27_1
L27_1 = "But instead of being happy to see me, you're hiding who you are, so I guess the future you doesn't like me very much."
L26_1.m_Talk_DEU = L27_1
L27_1 = "But instead of being happy to see me, you're hiding who you are, so I guess the future you doesn't like me very much."
L26_1.m_Talk_FRA = L27_1
L27_1 = {}
L28_1 = "EP15_ACT2_INTERLUDE8@180#Talk"
L27_1.m_CutScenKey_Talk = L28_1
L28_1 = 227
L27_1.m_CutScenProcessKey = L28_1
