L28_1 = "YEONHWA_ADMIN_NULL_NULL"
L27_1.m_CharStrID = L28_1
L27_1.m_Pos = "R"
L28_1 = "미래에도 우리 두 사람이 행복한지 물어보고 싶었을 뿐인데."
L27_1.m_Talk_KOREA = L28_1
L27_1.m_fTalkTime = 0.03
L28_1 = "未来でも二人は幸せなのか聞きたかっただけなのに。"
L27_1.m_Talk_JPN = L28_1
L28_1 = "I only wanted to ask whether the two of us are still happy together in the future."
L27_1.m_Talk_ENG = L28_1
L28_1 = "我只是想問你，未來的我們是不是依舊過得幸福。"
L27_1.m_Talk_TWN = L28_1
L28_1 = "I only wanted to ask whether the two of us are still happy together in the future."
L27_1.m_Talk_DEU = L28_1
L28_1 = "I only wanted to ask whether the two of us are still happy together in the future."
L27_1.m_Talk_FRA = L28_1
