L29_1 = "SEOSAENG_ATELIER_ANAP_GAP"
L28_1.m_CharStrID = L29_1
L28_1.m_Pos = "C"
L29_1 = "...난 그대가 아는 주한이 아닐세. 내가 꿈에서 보았던 여인이 그대가 아니듯 말이지."
L28_1.m_Talk_KOREA = L29_1
L28_1.m_fTalkTime = 0.03
L29_1 = "……某はそなたの知っているシスイではない。某が夢で見た女がそなたではないように。"
L28_1.m_Talk_JPN = L29_1
L29_1 = "...I am not the Joo Han you know. Just as the woman I saw in my dream was not you."
L28_1.m_Talk_ENG = L29_1
L29_1 = "……我並不是所認識的周翰，就像在我夢裡見到的那位女子也不是你一樣。"
L28_1.m_Talk_TWN = L29_1
L29_1 = "...I am not the Joo Han you know. Just as the woman I saw in my dream was not you."
L28_1.m_Talk_DEU = L29_1
L29_1 = "...I am not the Joo Han you know. Just as the woman I saw in my dream was not you."
L28_1.m_Talk_FRA = L29_1
