L30_1.m_CharStrID = L31_1
L30_1.m_Pos = "R"
L31_1 = "어휴- 아는 척하기 싫으면 어려운 소리 말고, 이것 하나만 대답해줘요."
L30_1.m_Talk_KOREA = L31_1
L30_1.m_fTalkTime = 0.03
L31_1 = "はあ……知ったかぶりしたくないのなら難しいこと言ってないで、これだけ答えてください。"
L30_1.m_Talk_JPN = L31_1
L31_1 = "Ugh. If you don't want to act like you know me, then forget the cryptic talk and just answer this one thing."
L30_1.m_Talk_ENG = L31_1
L31_1 = "唉—如果不想裝熟，就別說那些難懂的話了，只要回答我一個問題就好。"
