L37_1 = "SEOSAENG_ATELIER_ANAP_GAP"
L36_1.m_CharStrID = L37_1
L37_1 = "지난 긴 세월 동안 난 많은 것을 배웠지만, 내가 그대에게 남기고픈 말은 하나요."
L36_1.m_Talk_KOREA = L37_1
L36_1.m_fTalkTime = 0.03
L37_1 = "これまでの長い年月の間にたくさんのことを学んできたが、某がそなたに残したい言葉は一つだ。"
L36_1.m_Talk_JPN = L37_1
L37_1 = "Over the long years, I have learned many things, but there is only one thing I wish to leave you with."
L36_1.m_Talk_ENG = L37_1
L37_1 = "在漫長的歲月裡，我學會了很多事，但有一句話想留給你。"
L36_1.m_Talk_TWN = L37_1
L37_1 = "Over the long years, I have learned many things, but there is only one thing I wish to leave you with."
L36_1.m_Talk_DEU = L37_1
L37_1 = "Over the long years, I have learned many things, but there is only one thing I wish to leave you with."
L36_1.m_Talk_FRA = L37_1
