L39_1 = "EP15_ACT2_INTERLUDE8@187#Talk"
L38_1.m_CutScenKey_Talk = L39_1
L39_1 = 238
L38_1.m_CutScenProcessKey = L39_1
L38_1.m_CutScenID = 696
L38_1.m_CutScenStrID = "EP15_ACT2_INTERLUDE8"
L38_1.m_bWaitClick = true
L38_1.m_fWaitTime = 0
L39_1 = "SEOSAENG_ATELIER_ANAP_GAP"
L38_1.m_CharStrID = L39_1
L39_1 = "다가올 미래를 염려하지 말고, 오늘날 곁에 머무는 행복을 기꺼이 누리시게."
L38_1.m_Talk_KOREA = L39_1
L38_1.m_fTalkTime = 0.03
L39_1 = "迫りくる未来を憂うのではなく、今日そなたのそばにある幸福を存分に味わいたまえ。"
L38_1.m_Talk_JPN = L39_1
L39_1 = "Don't worry about the future to come, and gladly cherish the happiness that stays by your side today."
L38_1.m_Talk_ENG = L39_1
L39_1 = "不要對尚未到來的未來感到憂慮，好好享受今天陪伴在你身邊的幸福。"
L38_1.m_Talk_TWN = L39_1
L39_1 = "Don't worry about the future to come, and gladly cherish the happiness that stays by your side today."
L38_1.m_Talk_DEU = L39_1
L39_1 = "Don't worry about the future to come, and gladly cherish the happiness that stays by your side today."
